insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000001', 'home', 'home', 'الرئيسية', '{"title":"نقل سياحي وليموزين في مصر — احجز سيارة بسائق","description":"احجز سيارة حديثة بسائق محترف في أي مكان بمصر — استقبال مطارات وتنقلات داخل المدن وبينها وجولات سياحية ومناسبات، بأسعار واضحة وحجز يكتمل في دقائق."}'::jsonb, true, 0)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000000101', 'a0000000-0000-4000-8000-000000000001', 'hero', '{"headline":"سيارتك بسائق محترف في كل مصر","sub":"استقبال من المطار، تنقلات داخل المدينة وبين المحافظات، جولات سياحية ومناسبات — احجز في دقائق واترك الطريق علينا."}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000000102', 'a0000000-0000-4000-8000-000000000001', 'services-grid', '{"title":"خدماتنا","sub":"ست خدمات نقل متكاملة تغطي كل ما تحتاجه في تنقلاتك داخل مصر."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000000103', 'a0000000-0000-4000-8000-000000000001', 'fleet', '{"title":"أسطول يناسب كل رحلة","sub":"أربع فئات من السيارات الحديثة — من السيدان الأنيقة إلى الباصات الكبيرة — اختر ما يناسب عدد ركابك وحقائبك."}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000000104', 'a0000000-0000-4000-8000-000000000001', 'why-us', '{"title":"لماذا يختارنا المسافرون؟","sub":"لأن راحتك على الطريق لا تقبل المساومة."}'::jsonb, 3, true),
  ('b0000000-0000-4000-8000-000000000105', 'a0000000-0000-4000-8000-000000000001', 'cta-band', '{"title":"جاهز للانطلاق؟ احجز رحلتك الآن","note":"فريقنا متاح على مدار الساعة للرد على استفساراتك وتأكيد حجزك."}'::jsonb, 4, true),
  ('b0000000-0000-4000-8000-000000000106', 'a0000000-0000-4000-8000-000000000001', 'contact', '{"title":"تواصل معنا","sub":"اختر القناة الأقرب إليك — نرد سريعاً على مدار الساعة."}'::jsonb, 5, true)
insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000002', 'airport-transfer', 'service', 'استقبال المطارات', '{"title":"استقبال المطارات في مصر — توصيل من وإلى المطار","description":"خدمة استقبال وتوصيل من جميع مطارات مصر على مدار الساعة: سائق بانتظارك بلوحة تحمل اسمك، متابعة مواعيد الرحلات الجوية، وسيارات حديثة بسعر ثابت تعرفه قبل الحجز."}'::jsonb, true, 10)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000000201', 'a0000000-0000-4000-8000-000000000002', 'page-hero', '{"title":"استقبال وتوصيل المطارات","sub":"من لحظة هبوط طائرتك حتى باب فندقك — سائق محترف بانتظارك بلوحة تحمل اسمك في أي مطار من مطارات مصر.","ctaLabel":"احجز استقبالك الآن"}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000000202', 'a0000000-0000-4000-8000-000000000002', 'rich-text', '{"body":"رحلتك تبدأ من المطار، ولحظة الوصول الأولى تحدد انطباعك عن الرحلة كلها. لذلك نوفر خدمة استقبال وتوصيل تغطي جميع مطارات مصر — القاهرة الدولي، برج العرب، الغردقة، شرم الشيخ، الأقصر وأسوان — على مدار الساعة طوال أيام الأسبوع.\n\nنتابع موعد رحلتك الجوية أولاً بأول، فإذا تأخرت الطائرة تأخر السائق معها دون أي رسوم إضافية. ستجد سائقك في صالة الوصول حاملاً لوحة باسمك، يساعدك في حقائبك ويرافقك مباشرة إلى سيارة نظيفة مكيفة جاهزة للانطلاق.\n\nالسعر ثابت ومعلن قبل تأكيد الحجز — لا عدادات ولا مفاوضات ولا رسوم انتظار خفية. اختر فئة السيارة المناسبة لعدد المسافرين والحقائب، وسنتولى نحن كل التفاصيل من لحظة الهبوط حتى الوصول بأمان."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000000203', 'a0000000-0000-4000-8000-000000000002', 'features', '{"title":"لماذا استقبال المطار معنا؟","items":[{"title":"متابعة الرحلات الجوية","text":"نراقب موعد هبوط طائرتك لحظة بلحظة — التأخير علينا لا عليك."},{"title":"استقبال بلوحة الاسم","text":"سائقك بانتظارك داخل صالة الوصول بلوحة تحمل اسمك."},{"title":"سعر ثابت معلن","text":"تعرف التكلفة كاملة قبل الحجز — بلا عدادات أو رسوم مفاجئة."},{"title":"متاح على مدار الساعة","text":"رحلات فجرية أو وصول متأخر ليلاً — نعمل ٢٤ ساعة طوال الأسبوع."}]}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000000204', 'a0000000-0000-4000-8000-000000000002', 'faq', '{"title":"أسئلة شائعة عن استقبال المطارات","items":[{"q":"ماذا يحدث إذا تأخرت رحلتي الجوية؟","a":"نتابع حالة الرحلة تلقائياً ويُعدَّل موعد الاستقبال حسب موعد الهبوط الفعلي دون أي رسوم إضافية."},{"q":"كيف أجد السائق عند الوصول؟","a":"ستجد السائق في صالة الوصول حاملاً لوحة باسمك، ويصلك رقمه للتواصل المباشر قبل موعد الرحلة."},{"q":"هل تغطون جميع مطارات مصر؟","a":"نعم، نخدم مطارات القاهرة وبرج العرب والغردقة وشرم الشيخ والأقصر وأسوان وغيرها على مدار الساعة."},{"q":"هل ينتظرني السائق إذا تأخر خروجي من الجمارك؟","a":"نعم، يشمل الحجز فترة انتظار مجانية كافية لإنهاء إجراءات الوصول واستلام الحقائب."}]}'::jsonb, 3, true),
  ('b0000000-0000-4000-8000-000000000205', 'a0000000-0000-4000-8000-000000000002', 'cta-band', '{"title":"احجز استقبالك من المطار الآن","note":"أخبرنا برقم رحلتك وموعد الوصول — ونحن نتولى الباقي."}'::jsonb, 4, true)
insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000003', 'city-rides', 'service', 'التنقل داخل المدينة', '{"title":"التنقل داخل المدينة — سيارة خاصة بسائق بالساعة","description":"سيارة خاصة بسائق محترف داخل القاهرة والإسكندرية وكبرى مدن مصر — بالمشوار أو بالساعة أو باليوم، لمشاويرك واجتماعاتك وجولاتك بأسعار واضحة ومواعيد دقيقة."}'::jsonb, true, 11)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000000301', 'a0000000-0000-4000-8000-000000000003', 'page-hero', '{"title":"تنقل داخل مدينتك براحة تامة","sub":"سيارة حديثة بسائق محترف تحت تصرفك — لمشاويرك واجتماعاتك وجولاتك داخل القاهرة والإسكندرية وكبرى المدن المصرية.","ctaLabel":"احجز مشوارك"}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000000302', 'a0000000-0000-4000-8000-000000000003', 'rich-text', '{"body":"وسط زحام المدن الكبرى، يصبح أثمن ما تملكه هو وقتك وراحة بالك. نوفر لك سيارة خاصة بسائق محترف يعرف شوارع مدينتك واختصاراتها، يقلّك من الباب إلى الباب في مواعيد دقيقة — دون عناء البحث عن سيارة أو موقف.\n\nاحجز بالمشوار الواحد، أو بالساعة، أو ليوم كامل تتنقل فيه بحرية بين اجتماعاتك وزياراتك ومشترياتك والسيارة بانتظارك أينما توقفت. الخدمة متاحة داخل القاهرة الكبرى والإسكندرية وكبرى مدن المحافظات.\n\nسياراتنا حديثة نظيفة مكيفة، وسائقونا ملتزمون بالمواعيد وأصول التعامل الراقي — لتصل إلى وجهتك بمظهر يليق بك وذهن صافٍ لما هو أهم."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000000303', 'a0000000-0000-4000-8000-000000000003', 'features', '{"title":"مزايا التنقل معنا","items":[{"title":"حجز مرن","text":"بالمشوار أو بالساعة أو باليوم الكامل — أنت تحدد والسيارة تحت تصرفك."},{"title":"سائقون يعرفون المدينة","text":"خبرة حقيقية بالشوارع والاختصارات وأوقات الذروة لتصل في الموعد."},{"title":"خصوصية وراحة","text":"سيارة خاصة بك وحدك — لا مشاركة ولا انتظار ولا مفاوضات."},{"title":"أسعار معلنة","text":"تكلفة واضحة قبل تأكيد الحجز مهما تغير الطريق أو الزحام."}]}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000000304', 'a0000000-0000-4000-8000-000000000003', 'faq', '{"title":"أسئلة شائعة عن التنقل داخل المدينة","items":[{"q":"هل يمكنني حجز السيارة لعدة ساعات متواصلة؟","a":"نعم، نظام الحجز بالساعة يتيح لك إبقاء السيارة والسائق تحت تصرفك طوال المدة التي تحددها، مع إمكانية تمديدها أثناء الرحلة."},{"q":"هل تتوفر الخدمة في مدينتي؟","a":"نغطي القاهرة الكبرى والإسكندرية وكبرى مدن المحافظات، والتغطية تتوسع باستمرار — راسلنا للتأكد من توفر الخدمة في منطقتك."},{"q":"هل يمكن أن يتضمن المشوار أكثر من وجهة؟","a":"بالتأكيد — أخبرنا بخط سيرك عند الحجز أو وجّه السائق مباشرة أثناء الرحلة، فالسيارة تحت تصرفك."}]}'::jsonb, 3, true),
  ('b0000000-0000-4000-8000-000000000305', 'a0000000-0000-4000-8000-000000000003', 'cta-band', '{"title":"مشوارك القادم أسهل مما تتخيل","note":"احجز الآن وستكون السيارة عند بابك في الموعد تماماً."}'::jsonb, 4, true)
insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000004', 'intercity-travel', 'service', 'السفر عبر المدن', '{"title":"السفر بين المحافظات — سيارة خاصة بسائق","description":"رحلات من الباب إلى الباب بين جميع محافظات مصر بسيارات حديثة وسائقين محترفين — ذهاب فقط أو ذهاب وعودة مع ساعات انتظار، وسعر نهائي واضح قبل الانطلاق."}'::jsonb, true, 12)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000000401', 'a0000000-0000-4000-8000-000000000004', 'page-hero', '{"title":"سافر بين المحافظات براحة وأمان","sub":"رحلات من الباب إلى الباب بين جميع محافظات مصر — سيارات حديثة وسائقون محترفون وأسعار تعرفها قبل أن تنطلق.","ctaLabel":"احجز رحلتك"}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000000402', 'a0000000-0000-4000-8000-000000000004', 'rich-text', '{"body":"السفر بين المدن لا يعني التقيد بمواعيد القطارات أو زحام مواقف الأتوبيسات. مع خدمة السفر عبر المدن، تنطلق من باب بيتك في الموعد الذي تختاره، وتصل إلى وجهتك مباشرة دون محطات أو انتظار.\n\nنغطي الرحلات بين جميع محافظات مصر: من القاهرة إلى الإسكندرية والساحل الشمالي، ومن الغردقة إلى الأقصر وأسوان، وكل ما بينها. سيارات حديثة تخضع لصيانة دورية، وسائقون محترفون معتادون على الطرق السريعة والقيادة الطويلة.\n\nاختر ذهاباً فقط أو ذهاباً وعودة، وأضف ساعات انتظار إن كانت زيارتك قصيرة — والسعر النهائي أمامك واضحاً قبل تأكيد الحجز، بلا تكاليف خفية."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000000403', 'a0000000-0000-4000-8000-000000000004', 'features', '{"title":"مزايا السفر معنا","items":[{"title":"من الباب إلى الباب","text":"انطلاق من عنوانك ووصول إلى وجهتك مباشرة دون محطات."},{"title":"تغطية شاملة","text":"رحلات بين جميع محافظات مصر ذهاباً فقط أو ذهاباً وعودة."},{"title":"سيارات مجهزة للطرق الطويلة","text":"صيانة دورية وتكييف قوي ومساحة مريحة للحقائب."},{"title":"سعر نهائي واضح","text":"التكلفة كاملة معلنة قبل الانطلاق — بلا مفاجآت على الطريق."}]}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000000404', 'a0000000-0000-4000-8000-000000000004', 'faq', '{"title":"أسئلة شائعة عن السفر بين المحافظات","items":[{"q":"هل يمكن حجز رحلة ذهاب وعودة في نفس اليوم؟","a":"نعم، اختر ذهاباً وعودة وحدد ساعات الانتظار التي تحتاجها، وسيبقى السائق بانتظارك حتى انتهاء زيارتك."},{"q":"هل يتوقف السائق للاستراحة أثناء الطريق؟","a":"بالطبع — يمكنك طلب التوقف للاستراحة أو تناول الطعام في الاستراحات المناسبة على الطريق متى شئت."},{"q":"كيف تُحسب تكلفة الرحلة؟","a":"تُحسب التكلفة بناءً على المسافة وفئة السيارة وتفاصيل الرحلة كالذهاب والعودة وساعات الانتظار — وتظهر لك كاملة قبل تأكيد الحجز."}]}'::jsonb, 3, true),
  ('b0000000-0000-4000-8000-000000000405', 'a0000000-0000-4000-8000-000000000004', 'cta-band', '{"title":"محافظتك القادمة على بُعد حجز واحد","note":"أخبرنا بنقطة الانطلاق والوجهة — واترك الطريق علينا."}'::jsonb, 4, true)
insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000005', 'tours', 'service', 'الجولات السياحية', '{"title":"جولات سياحية خاصة بسيارة وسائق في مصر","description":"جولات سياحية خاصة في مصر بسيارة حديثة وسائق يعرف المزارات — صمم برنامجك بحرية بين الأهرامات والمتاحف والمدن السياحية، ليوم واحد أو عدة أيام بأسعار واضحة."}'::jsonb, true, 13)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000000501', 'a0000000-0000-4000-8000-000000000005', 'page-hero', '{"title":"اكتشف مصر بجولة خاصة على ذوقك","sub":"سيارة خاصة وسائق يعرف الطريق والمزارات — صمم برنامجك بحرية وتنقل بين المعالم في راحة تامة.","ctaLabel":"خطط جولتك"}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000000502', 'a0000000-0000-4000-8000-000000000005', 'rich-text', '{"body":"من أهرامات الجيزة والمتحف المصري الكبير إلى معابد الأقصر وشواطئ البحر الأحمر — مصر مليئة بما يستحق الاكتشاف، وأجمل طريقة لاكتشافها جولة خاصة تتحكم أنت في إيقاعها.\n\nاختر مزاراتك وحدد مواعيدك، وسيتولى سائقنا الطريق والمواقف والتوقيت، بخبرة من يعرف أفضل أوقات الزيارة وأقصر الطرق بين المعالم. توقف حيث شئت والتقط صورك بلا استعجال — السيارة بانتظارك دائماً.\n\nالجولات متاحة ليوم واحد أو لعدة أيام تشمل التنقل بين المدن السياحية، بسيارات تناسب الأفراد والعائلات والمجموعات على حد سواء."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000000503', 'a0000000-0000-4000-8000-000000000005', 'features', '{"title":"لماذا جولتك معنا أجمل؟","items":[{"title":"برنامج مرن بالكامل","text":"أنت تختار المزارات والمواعيد — لا برامج جاهزة مفروضة عليك."},{"title":"سائق يعرف الطريق","text":"خبرة بالمزارات وأفضل أوقات الزيارة وأقصر الطرق بينها."},{"title":"راحة طوال اليوم","text":"سيارة مكيفة بانتظارك عند كل مزار — بلا بحث عن مواصلات."},{"title":"جولات ليوم أو أكثر","text":"من جولة سريعة بالقاهرة إلى برنامج متكامل يجوب المدن السياحية."}]}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000000504', 'a0000000-0000-4000-8000-000000000005', 'faq', '{"title":"أسئلة شائعة عن الجولات السياحية","items":[{"q":"هل يشمل السعر تذاكر دخول المزارات؟","a":"السعر يشمل السيارة والسائق والتنقل، وتُدفع تذاكر الدخول في المزار مباشرة — ويمكننا إخبارك بأسعارها المتوقعة مسبقاً."},{"q":"هل يمكن تعديل البرنامج أثناء الجولة؟","a":"نعم، البرنامج مرن بالكامل — أضف مزاراً أو تجاوز آخر بالتنسيق مع السائق أثناء الجولة."},{"q":"هل تناسب الجولات العائلات والمجموعات؟","a":"بالتأكيد — لدينا فئات سيارات تناسب الأفراد والعائلات والمجموعات الكبيرة، من السيدان حتى الباص المجهز."}]}'::jsonb, 3, true),
  ('b0000000-0000-4000-8000-000000000505', 'a0000000-0000-4000-8000-000000000005', 'cta-band', '{"title":"مصر بانتظارك — ابدأ جولتك","note":"أخبرنا بما تحب أن تراه وسنقترح عليك البرنامج الأنسب."}'::jsonb, 4, true)
insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000006', 'events', 'service', 'المناسبات الخاصة', '{"title":"سيارات بسائق للمناسبات — زفاف وخطوبة وتخرج","description":"سيارات أنيقة بسائقين بمظهر رسمي لمناسباتك الخاصة في مصر: تنسيق تحركات الزفاف ونقل الضيوف ومرافقة جلسات التصوير — مواعيد دقيقة وأسعار واضحة شاملة."}'::jsonb, true, 14)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000000601', 'a0000000-0000-4000-8000-000000000006', 'page-hero', '{"title":"مناسبتك تستحق وصولاً مميزاً","sub":"زفاف أو خطوبة أو تخرج أو عشاء مهم — سيارات أنيقة وسائقون بمظهر لائق ومواعيد لا تتأخر ثانية.","ctaLabel":"احجز ليوم مناسبتك"}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000000602', 'a0000000-0000-4000-8000-000000000006', 'rich-text', '{"body":"في يومك المميز، آخر ما تريد التفكير فيه هو الطريق والمواقف والمواعيد. نتولى عنك تفاصيل التنقل كاملة: سيارة أنيقة نظيفة تليق بالمناسبة، وسائق بمظهر رسمي يعرف قيمة اللحظة التي تعيشها.\n\nننسق تحركات يوم الزفاف من التجهيز حتى القاعة، وننقل ضيوفك في مواعيد مدروسة، ونرافق جلسات التصوير بين المواقع. وللمناسبات الأخرى — خطوبة أو تخرج أو عيد ميلاد أو عشاء عمل — نصلك في الموعد بدقة وأناقة.\n\nأخبرنا بتفاصيل مناسبتك وعدد ضيوفك، وسنقترح عليك خطة التحرك والسيارات المناسبة بسعر واضح شامل."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000000603', 'a0000000-0000-4000-8000-000000000006', 'features', '{"title":"ما الذي نقدمه لمناسبتك؟","items":[{"title":"سيارات تليق بالمناسبة","text":"أحدث الموديلات بنظافة تامة ومظهر أنيق يكمل صورة يومك."},{"title":"تنسيق كامل للتحركات","text":"خطة زمنية مدروسة لتحركاتك وتحركات ضيوفك دون تأخير."},{"title":"سائقون بمظهر رسمي","text":"التزام تام بالمواعيد وأصول التعامل الراقي طوال المناسبة."}]}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000000604', 'a0000000-0000-4000-8000-000000000006', 'faq', '{"title":"أسئلة شائعة عن نقل المناسبات","items":[{"q":"هل يمكن تزيين السيارة ليوم الزفاف؟","a":"نعم، يمكن تجهيز السيارة بالتزيين الذي تفضله بالتنسيق المسبق عند الحجز."},{"q":"هل توفرون سيارات لنقل الضيوف أيضاً؟","a":"بالتأكيد — ننسق أسطولاً متكاملاً من السيارات والميني باص والباصات لنقل ضيوفك في مواعيد مدروسة."},{"q":"متى يُفضل الحجز للمناسبات؟","a":"ننصح بالحجز قبل المناسبة بأسبوع على الأقل لضمان توفر السيارات المطلوبة، خاصة في مواسم الأفراح."}]}'::jsonb, 3, true),
  ('b0000000-0000-4000-8000-000000000605', 'a0000000-0000-4000-8000-000000000006', 'cta-band', '{"title":"دع الطريق علينا وتفرغ لفرحتك","note":"احجز مبكراً لضمان توفر السيارة الأنسب ليوم مناسبتك."}'::jsonb, 4, true)
insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000007', 'conferences', 'service', 'الحفلات والمؤتمرات', '{"title":"نقل المؤتمرات والوفود والحفلات — أسطول منسق","description":"خدمات نقل متكاملة للمؤتمرات والمعارض والحفلات والوفود في مصر: خطة تحرك تفصيلية ومنسق ميداني وأسطول موحد من السيارات الفاخرة والباصات — بعرض سعر شامل."}'::jsonb, true, 15)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000000701', 'a0000000-0000-4000-8000-000000000007', 'page-hero', '{"title":"أساطيل منسقة لفعاليتك الكبيرة","sub":"مؤتمرات ومعارض وحفلات ووفود رسمية — إدارة تحركات متكاملة بأسطول موحد ومنسق ميداني ومواعيد بالدقيقة.","ctaLabel":"اطلب عرض سعر"}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000000702', 'a0000000-0000-4000-8000-000000000007', 'rich-text', '{"body":"نجاح الفعاليات الكبيرة يقاس بأدق تفاصيلها — ووصول الضيوف في الموعد أولها. نوفر لشركات تنظيم الفعاليات والجهات الرسمية والشركات أسطولاً منسقاً يدير تحركات المؤتمرات والمعارض والحفلات والوفود من البداية إلى النهاية.\n\nنبدأ بخطة تحرك تفصيلية: استقبال الضيوف من المطارات والفنادق، جدول نقل يومي بين مقار الإقامة وقاعات الفعالية، ومنسق ميداني يتابع التنفيذ لحظة بلحظة ويتعامل مع أي طارئ فوراً.\n\nمن سيارات فاخرة لكبار الشخصيات إلى باصات لنقل المشاركين، نجهز التوليفة المناسبة لحجم فعاليتك — بعقد واضح وفاتورة موحدة وتقارير تحرك عند الطلب."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000000703', 'a0000000-0000-4000-8000-000000000007', 'features', '{"title":"ما الذي يميز نقل فعاليتك معنا؟","items":[{"title":"خطة تحرك متكاملة","text":"جدولة كاملة لاستقبال وتنقلات الضيوف طوال أيام الفعالية."},{"title":"منسق ميداني","text":"متابعة حية للتنفيذ والتعامل الفوري مع أي تغيير طارئ."},{"title":"أسطول متنوع وموحد","text":"من سيارات كبار الشخصيات إلى باصات المشاركين — بمستوى واحد من الجودة."},{"title":"تعاقد وفاتورة موحدة","text":"عرض سعر شامل وعقد واضح وتقارير تحرك للجهات المنظمة."}]}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000000704', 'a0000000-0000-4000-8000-000000000007', 'faq', '{"title":"أسئلة شائعة عن نقل الفعاليات","items":[{"q":"هل تتعاملون مع شركات تنظيم الفعاليات؟","a":"نعم، نعمل كشريك نقل لشركات التنظيم والجهات الرسمية والشركات، بعقود وأسعار خاصة للفعاليات المتكررة."},{"q":"كم يلزم من الوقت لتجهيز نقل مؤتمر كامل؟","a":"للفعاليات الكبيرة ننصح بالتواصل قبل أسبوعين على الأقل لإعداد خطة التحرك وتخصيص الأسطول والمنسقين."},{"q":"هل يمكن توفير سيارات لكبار الشخصيات ضمن الأسطول؟","a":"بالتأكيد — نخصص سيارات فاخرة بسائقين مدربين على بروتوكول التعامل مع كبار الشخصيات والوفود الرسمية."}]}'::jsonb, 3, true),
  ('b0000000-0000-4000-8000-000000000705', 'a0000000-0000-4000-8000-000000000007', 'cta-band', '{"title":"فعاليتك القادمة بتحركات منضبطة","note":"شاركنا تفاصيل الفعالية وسيصلك عرض سعر متكامل خلال يوم عمل."}'::jsonb, 4, true)
insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000008', 'cairo-alexandria', 'corridor', 'نقل سياحي من القاهرة إلى الإسكندرية', '{"title":"نقل سياحي من القاهرة إلى الإسكندرية بسيارة خاصة","description":"احجز سيارة خاصة بسائق من القاهرة إلى الإسكندرية — رحلة من الباب إلى الباب في نحو ثلاث ساعات، سيارات سيدان وSUV وميني باص وباص بأسعار ثابتة معلنة قبل التأكيد."}'::jsonb, true, 20)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000000801', 'a0000000-0000-4000-8000-000000000008', 'page-hero', '{"title":"نقل سياحي من القاهرة إلى الإسكندرية","sub":"رحلة مريحة من باب بيتك في القاهرة إلى أي عنوان في الإسكندرية — سيارة حديثة وسائق محترف وسعر واضح.","ctaLabel":"احجز رحلتك الآن"}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000000802', 'a0000000-0000-4000-8000-000000000008', 'rich-text', '{"body":"تمتد الرحلة بين القاهرة والإسكندرية نحو ٢٢٠ كيلومتراً عبر الطريق الصحراوي، وتستغرق عادة من ساعتين ونصف إلى ثلاث ساعات حسب حركة الطريق ونقطة الانطلاق. سيارتك تصلك حتى باب منزلك أو فندقك في الموعد المحدد، وتنطلق مباشرة دون محطات.\n\nيشمل الحجز سيارة حديثة مكيفة وسائقاً محترفاً معتاداً على الطريق الصحراوي، مع إمكانية التوقف للاستراحة متى شئت. اختر ذهاباً فقط أو ذهاباً وعودة مع ساعات انتظار إن كانت زيارتك ليوم واحد.\n\nتتوفر أربع فئات من السيارات على هذا المسار: سيدان للأفراد حتى ثلاثة ركاب، وSUV للعائلات حتى ستة، وميني باص للمجموعات المتوسطة، وباص للرحلات الكبيرة — ولكل فئة سعر ثابت معلن قبل التأكيد."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000000803', 'a0000000-0000-4000-8000-000000000008', 'faq', '{"title":"أسئلة شائعة عن مسار القاهرة — الإسكندرية","items":[{"q":"كم تستغرق الرحلة من القاهرة إلى الإسكندرية بالسيارة؟","a":"عادة من ساعتين ونصف إلى ثلاث ساعات عبر الطريق الصحراوي، حسب نقطة الانطلاق وحركة الطريق."},{"q":"هل يمكن الذهاب والعودة في نفس اليوم؟","a":"نعم، اختر ذهاباً وعودة وحدد ساعات الانتظار، وسيبقى السائق بانتظارك في الإسكندرية حتى موعد العودة."},{"q":"من أي مناطق القاهرة يمكن الانطلاق؟","a":"من أي عنوان داخل القاهرة الكبرى — المعادي ومدينة نصر والتجمع و٦ أكتوبر والشيخ زايد وغيرها — التحرك من باب بيتك مباشرة."}]}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000000804', 'a0000000-0000-4000-8000-000000000008', 'cta-band', '{"title":"القاهرة — الإسكندرية في راحة تامة","note":"احجز الآن وحدد موعد انطلاقك — والسعر النهائي أمامك قبل التأكيد."}'::jsonb, 3, true)
insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000009', 'cairo-north-coast', 'corridor', 'نقل سياحي من القاهرة إلى الساحل الشمالي', '{"title":"نقل من القاهرة إلى الساحل الشمالي — سيارة بسائق","description":"سيارة خاصة بسائق من القاهرة إلى الساحل الشمالي والعلمين ومارينا ورأس الحكمة — من باب بيتك حتى بوابة قريتك، بسيارات حديثة تتسع لعائلتك وحقائبك وسعر واضح."}'::jsonb, true, 21)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000000901', 'a0000000-0000-4000-8000-000000000009', 'page-hero', '{"title":"نقل سياحي من القاهرة إلى الساحل الشمالي","sub":"من باب بيتك حتى بوابة قريتك — رحلة مصيف مريحة بسيارة حديثة تتسع لعائلتك وحقائبك.","ctaLabel":"احجز رحلتك الآن"}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000000902', 'a0000000-0000-4000-8000-000000000009', 'rich-text', '{"body":"يقصد المصطافون الساحل الشمالي من العجمي حتى مارينا والعلمين الجديدة ورأس الحكمة، وتتراوح المسافة من القاهرة بين ٢٥٠ و٣٥٠ كيلومتراً حسب القرية، عبر طريق وادي النطرون أو محور الضبعة. تستغرق الرحلة عادة من ثلاث إلى أربع ساعات.\n\nاحجز سيارتك بسائق لتنطلق من باب بيتك محملاً بأمتعتك حتى بوابة قريتك مباشرة — دون معاناة القيادة الطويلة أو البحث عن مواقف. يشمل الحجز التوقف للاستراحة على الطريق، وخيار الذهاب والعودة لمن يقضي إجازة قصيرة.\n\nتناسب السيدان الأفراد، بينما تتسع الـ SUV للعائلة وحقائب المصيف، والميني باص والباص للعائلات الكبيرة والتجمعات — اختر فئتك وسيظهر السعر النهائي قبل تأكيد الحجز."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000000903', 'a0000000-0000-4000-8000-000000000009', 'faq', '{"title":"أسئلة شائعة عن مسار القاهرة — الساحل الشمالي","items":[{"q":"كم تستغرق الرحلة من القاهرة إلى الساحل الشمالي؟","a":"من ثلاث إلى أربع ساعات تقريباً حسب موقع القرية — فالساحل يمتد من العجمي حتى رأس الحكمة ومرسى مطروح."},{"q":"هل يوصلني السائق حتى داخل القرية؟","a":"نعم، التوصيل حتى بوابة قريتك أو باب شاليهك متى سمحت بوابات القرية بالدخول."},{"q":"هل تتسع السيارات لحقائب المصيف الكثيرة؟","a":"ننصح بفئة SUV أو الميني باص للعائلات — مساحات تخزين واسعة تتسع لحقائب إجازة كاملة."}]}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000000904', 'a0000000-0000-4000-8000-000000000009', 'cta-band', '{"title":"مصيفك يبدأ من باب بيتك","note":"احجز الآن ووفر على نفسك عناء الطريق وزحام المواقف."}'::jsonb, 3, true)
insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000010', 'cairo-hurghada', 'corridor', 'نقل سياحي من القاهرة إلى الغردقة', '{"title":"نقل من القاهرة إلى الغردقة — سيارة خاصة بسائق","description":"احجز سيارة بسائق من القاهرة إلى الغردقة والجونة وسهل حشيش — رحلة نحو خمس ساعات عبر طريق الزعفرانة الساحلي بسيارات حديثة وسعر ثابت معلن قبل تأكيد الحجز."}'::jsonb, true, 22)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000001001', 'a0000000-0000-4000-8000-000000000010', 'page-hero', '{"title":"نقل سياحي من القاهرة إلى الغردقة","sub":"رحلة ساحلية مريحة على طريق البحر الأحمر — سيارة حديثة وسائق معتاد على الطريق وسعر ثابت معلن.","ctaLabel":"احجز رحلتك الآن"}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000001002', 'a0000000-0000-4000-8000-000000000010', 'rich-text', '{"body":"تبعد الغردقة عن القاهرة نحو ٤٥٠ كيلومتراً عبر طريق العين السخنة والزعفرانة الساحلي، وتستغرق الرحلة بالسيارة نحو خمس ساعات مع استراحة في منتصف الطريق — على طريق سريع يطل معظمه على ساحل البحر الأحمر.\n\nيشمل الحجز سيارة حديثة مكيفة بسائق معتاد على الطريق الساحلي، مع التوقف في الاستراحات المجهزة متى احتجت. الانطلاق من أي عنوان في القاهرة، والوصول حتى باب فندقك أو قريتك في الغردقة أو الجونة أو سهل حشيش.\n\nاختر من أربع فئات: سيدان للأفراد، وSUV للعائلات ومعدات الرحلة، وميني باص وباص للمجموعات — والسعر النهائي ثابت ومعلن قبل تأكيد الحجز."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000001003', 'a0000000-0000-4000-8000-000000000010', 'faq', '{"title":"أسئلة شائعة عن مسار القاهرة — الغردقة","items":[{"q":"كم تستغرق الرحلة من القاهرة إلى الغردقة بالسيارة؟","a":"نحو خمس ساعات عبر طريق الزعفرانة الساحلي، شاملة استراحة قصيرة في منتصف الطريق."},{"q":"هل يمكن التوصيل إلى الجونة أو سهل حشيش؟","a":"نعم، نغطي الغردقة وامتدادها السياحي بالكامل — الجونة وسهل حشيش ومكادي باي — حتى باب فندقك."},{"q":"هل يمكن الانطلاق في ساعات الفجر أو الليل؟","a":"نعم، الخدمة متاحة على مدار الساعة — حدد موعد انطلاقك وسيكون السائق عند بابك في الوقت المحدد."}]}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000001004', 'a0000000-0000-4000-8000-000000000010', 'cta-band', '{"title":"البحر الأحمر أقرب مما تظن","note":"احجز رحلتك إلى الغردقة الآن بسعر ثابت بلا مفاجآت."}'::jsonb, 3, true)
insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000011', 'cairo-sharm-el-sheikh', 'corridor', 'نقل سياحي من القاهرة إلى شرم الشيخ', '{"title":"نقل من القاهرة إلى شرم الشيخ — سيارة بسائق","description":"سيارة خاصة بسائق من القاهرة إلى شرم الشيخ — رحلة نحو ست ساعات عبر نفق الشهيد أحمد حمدي حتى باب فندقك، بأربع فئات سيارات وسعر ثابت معلن قبل تأكيد الحجز."}'::jsonb, true, 23)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000001101', 'a0000000-0000-4000-8000-000000000011', 'page-hero', '{"title":"نقل سياحي من القاهرة إلى شرم الشيخ","sub":"من باب بيتك في القاهرة إلى قلب مدينة السلام — رحلة آمنة بسيارة حديثة وسائق خبير بطريق سيناء.","ctaLabel":"احجز رحلتك الآن"}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000001102', 'a0000000-0000-4000-8000-000000000011', 'rich-text', '{"body":"تبعد شرم الشيخ عن القاهرة نحو ٥٠٠ كيلومتر عبر نفق الشهيد أحمد حمدي ثم الطريق الساحلي لخليج السويس، وتستغرق الرحلة نحو ست ساعات شاملة الاستراحات ونقاط التفتيش المعتادة على الطريق.\n\nيشمل الحجز سيارة حديثة مكيفة وسائقاً خبيراً بطريق سيناء وإجراءاته، مع استراحات مجدولة على الطريق. ننطلق من أي عنوان في القاهرة الكبرى ونوصلك حتى باب فندقك في خليج نعمة أو هضبة أم السيد أو أي منطقة بشرم الشيخ.\n\nالفئات الأربع متاحة على المسار — سيدان وSUV وميني باص وباص — بأسعار ثابتة حسب الفئة تظهر لك كاملة قبل تأكيد الحجز، ذهاباً فقط أو ذهاباً وعودة."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000001103', 'a0000000-0000-4000-8000-000000000011', 'faq', '{"title":"أسئلة شائعة عن مسار القاهرة — شرم الشيخ","items":[{"q":"كم تستغرق الرحلة من القاهرة إلى شرم الشيخ؟","a":"نحو ست ساعات شاملة الاستراحات ونقاط التفتيش، حسب حركة الطريق وموعد الانطلاق."},{"q":"هل أحتاج أوراقاً خاصة لدخول سيناء؟","a":"يكفي المصريين بطاقة رقم قومي سارية، ويُنصح الأجانب باصطحاب جواز السفر — وسائقنا معتاد على إجراءات نقاط التفتيش."},{"q":"هل السفر ليلاً متاح على هذا المسار؟","a":"نعم مع مراعاة المواعيد المنظمة للعبور على الطريق — ننسق معك أنسب موعد للانطلاق عند الحجز."}]}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000001104', 'a0000000-0000-4000-8000-000000000011', 'cta-band', '{"title":"شرم الشيخ على بُعد رحلة واحدة","note":"احجز الآن وسنتولى الطريق وإجراءاته حتى باب فندقك."}'::jsonb, 3, true)
insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000012', 'cairo-airport', 'corridor', 'توصيل من وإلى مطار القاهرة', '{"title":"توصيل مطار القاهرة — استقبال بسيارة خاصة","description":"استقبال وتوصيل من وإلى مطار القاهرة الدولي على مدار الساعة — متابعة الرحلات الجوية ولوحة باسمك وحساب دقيق لزحام القاهرة، بسيارات حديثة وسعر ثابت معلن."}'::jsonb, true, 24)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000001201', 'a0000000-0000-4000-8000-000000000012', 'page-hero', '{"title":"توصيل من وإلى مطار القاهرة الدولي","sub":"استقبال بلوحة اسمك في صالة الوصول، أو توصيل يحسب زحام القاهرة ويصل بك قبل إقلاع طائرتك بوقت كافٍ.","ctaLabel":"احجز مشوار المطار"}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000001202', 'a0000000-0000-4000-8000-000000000012', 'rich-text', '{"body":"مطار القاهرة الدولي هو بوابة مصر الأولى، والوصول إليه أو منه عبر زحام العاصمة يحتاج توقيتاً دقيقاً. تتراوح مدة المشوار بين ٣٠ و٩٠ دقيقة حسب منطقتك داخل القاهرة الكبرى وحالة المرور — ونحن نحسبها لك بدقة ونحدد موعد التحرك الأنسب.\n\nفي الاستقبال: نتابع موعد هبوط رحلتك وينتظرك السائق في صالة الوصول بلوحة تحمل اسمك مهما تأخرت الطائرة. وفي التوصيل: نصل إلى عنوانك قبل الموعد ونختار أفضل الطرق لتصل إلى صالة السفر مطمئناً قبل الإقلاع بوقت كافٍ.\n\nتتوفر جميع فئات السيارات من السيدان للمسافر الفردي حتى الباص لوفود العمل والمجموعات السياحية — بسعر ثابت معلن يشمل فترة انتظار مجانية كافية."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000001203', 'a0000000-0000-4000-8000-000000000012', 'faq', '{"title":"أسئلة شائعة عن توصيل مطار القاهرة","items":[{"q":"متى يجب التحرك من منزلي للحاق برحلتي؟","a":"نوصي بالوصول قبل الإقلاع بثلاث ساعات للرحلات الدولية، ونحدد لك موعد التحرك الأنسب حسب منطقتك وحالة المرور المتوقعة."},{"q":"أين أجد السائق عند وصولي إلى مطار القاهرة؟","a":"في صالة الوصول مباشرة بعد خروجك من الجمارك، حاملاً لوحة باسمك — ويصلك رقمه قبل الهبوط للتواصل المباشر."},{"q":"هل تغطون جميع مباني الركاب بالمطار؟","a":"نعم، نخدم جميع مباني الركاب بمطار القاهرة الدولي استقبالاً وتوصيلاً على مدار الساعة."}]}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000001204', 'a0000000-0000-4000-8000-000000000012', 'cta-band', '{"title":"مشوار المطار بلا توتر","note":"أخبرنا برقم رحلتك وسنتولى التوقيت والطريق والاستقبال."}'::jsonb, 3, true)
insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000013', 'alexandria-north-coast', 'corridor', 'نقل سياحي من الإسكندرية إلى الساحل الشمالي', '{"title":"نقل من الإسكندرية إلى الساحل الشمالي بسيارة","description":"سيارة خاصة بسائق من الإسكندرية إلى قرى الساحل الشمالي والعلمين ومارينا — استقبال من محطة القطار أو مطار برج العرب حتى بوابة قريتك، بأسعار ثابتة معلنة."}'::jsonb, true, 25)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000001301', 'a0000000-0000-4000-8000-000000000013', 'page-hero', '{"title":"نقل سياحي من الإسكندرية إلى الساحل الشمالي","sub":"مشوار قصير من الإسكندرية إلى قريتك على الساحل — سيارة مريحة وسائق يعرف مداخل القرى ومخارجها.","ctaLabel":"احجز رحلتك الآن"}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000001302', 'a0000000-0000-4000-8000-000000000013', 'rich-text', '{"body":"الإسكندرية هي البوابة الأقرب للساحل الشمالي: تبدأ قراه من العجمي على أطراف المدينة وتمتد عبر الطريق الساحلي الدولي حتى مارينا والعلمين الجديدة ورأس الحكمة. تتراوح الرحلة بين ساعة وساعتين ونصف حسب موقع قريتك.\n\nالخدمة مثالية للقادمين إلى الإسكندرية بالقطار أو عبر مطار برج العرب، ولأهل الإسكندرية المصطافين. ننقلك من المحطة أو المطار أو باب بيتك مباشرة حتى بوابة قريتك، مع مساحة كافية لحقائب المصيف.\n\nاختر السيدان للمشاوير الخفيفة، أو الـ SUV للعائلة، أو الميني باص والباص للتجمعات الكبيرة — بأسعار ثابتة حسب الفئة والمسافة تظهر قبل تأكيد الحجز."}'::jsonb, 1, true),
  ('b0000000-0000-4000-8000-000000001303', 'a0000000-0000-4000-8000-000000000013', 'faq', '{"title":"أسئلة شائعة عن مسار الإسكندرية — الساحل","items":[{"q":"كم تستغرق الرحلة من الإسكندرية إلى الساحل الشمالي؟","a":"من ساعة إلى ساعتين ونصف حسب موقع القرية — العجمي والقرى القريبة أسرع، والعلمين ورأس الحكمة أبعد."},{"q":"هل تستقبلون من محطة القطار أو مطار برج العرب؟","a":"نعم، نستقبلك من محطة مصر أو سيدي جابر أو مطار برج العرب مباشرة وننطلق بك إلى قريتك."},{"q":"هل يمكن حجز رحلة العودة مسبقاً؟","a":"بالتأكيد — احجز الذهاب والعودة معاً بموعدين منفصلين، وسيكون السائق عند بوابة قريتك في موعد العودة تماماً."}]}'::jsonb, 2, true),
  ('b0000000-0000-4000-8000-000000001304', 'a0000000-0000-4000-8000-000000000013', 'cta-band', '{"title":"من الإسكندرية إلى الساحل في ساعة","note":"احجز الآن وسنوصلك حتى بوابة قريتك بلا عناء."}'::jsonb, 3, true)
insert into public.pages (id, slug, kind, title, meta, published, sort) values
  ('a0000000-0000-4000-8000-000000000014', 'about', 'static', 'من نحن', '{"title":"من نحن — خدمات نقل سياحي في جميع أنحاء مصر","description":"تعرف على منصتنا لخدمات النقل السياحي في مصر: شبكة متعهدين معتمدين وأسطول حديث بأربع فئات ومعايير صارمة للجودة — سعر واضح وسيارة نظيفة وسائق يصل في موعده."}'::jsonb, true, 30)
insert into public.sections (id, page_id, type, content, sort, visible) values
  ('b0000000-0000-4000-8000-000000001401', 'a0000000-0000-4000-8000-000000000014', 'page-hero', '{"title":"من نحن","sub":"منصة مصرية متخصصة في خدمات النقل السياحي — نوصلك أينما أردت داخل مصر براحة وأمان وسعر واضح."}'::jsonb, 0, true),
  ('b0000000-0000-4000-8000-000000001402', 'a0000000-0000-4000-8000-000000000014', 'rich-text', '{"body":"بدأنا من سؤال بسيط: لماذا لا يزال حجز سيارة بسائق في مصر يحتاج مكالمات ومفاوضات وأسعاراً غامضة؟ فبنينا منصة تجعل الأمر بسهولة حجز غرفة فندق: تختار رحلتك، وترى سعرك، وتؤكد حجزك في دقائق.\n\nنعمل مع شبكة من المتعهدين المعتمدين في مختلف المحافظات، ونُخضع كل سيارة وكل سائق لمعايير واضحة في النظافة والحداثة والالتزام وأصول التعامل — لتحصل على المستوى نفسه من الخدمة في كل رحلة أياً كانت وجهتها.\n\nنغطي خدمات النقل السياحي بمختلف صورها: استقبال المطارات، والتنقل داخل المدن، والسفر بين المحافظات، والجولات السياحية، والمناسبات والمؤتمرات — بأسطول من أربع فئات يناسب الأفراد والعائلات والمجموعات.\n\nوعدنا لك ثلاثية لا نحيد عنها: سعر واضح تعرفه قبل الحجز، وسيارة نظيفة حديثة، وسائق محترف يصل في موعده. هكذا نعمل، وهكذا نحب أن يتذكرنا كل من سافر معنا."}'::jsonb, 1, true)
